const express = require('express');
const net = require('net');

const app = express();

// Parse DATABASE_URL from environment (format: postgres://user:pass@host:port/db)
function parseDbUrl(url) {
  if (!url) return null;
  const match = url.match(/postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)/);
  if (!match) return null;
  return { user: match[1], pass: match[2], host: match[3], port: parseInt(match[4]), database: match[5] };
}

// Check if Postgres is reachable by connecting to the database port
function checkDbHealth() {
  return new Promise((resolve) => {
    const dbConfig = parseDbUrl(process.env.DATABASE_URL);
    if (!dbConfig) {
      resolve({ ok: false, error: 'DATABASE_URL not configured' });
      return;
    }

    const socket = new net.Socket();
    const timeout = 5000;

    socket.setTimeout(timeout);

    socket.on('connect', () => {
      // Send PostgreSQL startup packet to authenticate
      // This is a minimal startup message
      const startupMessage = buildPostgresStartupMessage(dbConfig.database, dbConfig.user);
      socket.write(startupMessage);

      // Wait for response (either auth challenge or ready for query)
      socket.once('data', (data) => {
        const msgType = String.fromCharCode(data[0]);
        // 'R' = authentication, 'E' = error, 'Z' = ready for query
        if (msgType === 'Z' || msgType === 'R') {
          socket.destroy();
          resolve({ ok: true });
        } else if (msgType === 'E') {
          socket.destroy();
          resolve({ ok: false, error: 'database error' });
        } else {
          // For simplicity, consider connected if we get any response
          socket.destroy();
          resolve({ ok: true });
        }
      });

      socket.on('error', (err) => {
        socket.destroy();
        resolve({ ok: false, error: err.message });
      });
    });

    socket.on('timeout', () => {
      socket.destroy();
      resolve({ ok: false, error: 'connection timeout' });
    });

    socket.on('error', (err) => {
      resolve({ ok: false, error: err.message });
    });

    socket.connect(dbConfig.port, dbConfig.host);
  });
}

// Build minimal PostgreSQL startup message
function buildPostgresStartupMessage(database, user) {
  const protocol = 3 << 16; // Protocol version 3.0
  const userStr = `user\0${user}\0`;
  const dbStr = `database\0${database}\0`;
  const payload = `\0\0\0\0${protocol}` + userStr + dbStr + `\0`;
  const length = Buffer.byteLength(payload) + 4;
  return Buffer.concat([createInt32BE(length), Buffer.from(payload)]);
}

function createInt32BE(n) {
  const buf = Buffer.alloc(4);
  buf.writeUInt32BE(n, 0);
  return buf;
}

