function parseDatabaseUrl(url) {
  if (!url) return null;

  // Format: postgres://user:pass@host:port/database
  const match = url.match(/postgres:\/\/(?:[^:]+):(?:[^@]+)@([^:]+):(\d+)\/.*/);
